use std::env;
use std::process;

fn main() {
    let mut args = env::args();
    // Skip program name
    args.next();

    let mut count: i64 = 0;
    let mut sum: i64 = 0;
    let mut min: i64 = 0;
    let mut max: i64 = 0;
    let mut first = true;

    for arg in args {
        let value: i64 = match arg.parse::<i64>() {
            Ok(v) => v,
            Err(_) => {
                // Invalid integer
                process::exit(1);
            }
        };

        if first {
            count = 1;
            sum = value;
            min = value;
            max = value;
            first = false;
        } else {
            // count + 1
            count = match count.checked_add(1) {
                Some(c) => c,
                None => process::exit(1),
            };

            // sum + value
            sum = match sum.checked_add(value) {
                Some(s) => s,
                None => process::exit(1),
            };

            // min
            if value < min {
                min = value;
            }

            // max
            if value > max {
                max = value;
            }
        }
    }

    // Empty input is an error
    if first {
        process::exit(1);
    }

    println!("count={} sum={} min={} max={}", count, sum, min, max);
}

