use std::collections::HashMap;
use std::error::Error;
use std::fmt::{Display, Formatter, Result as FmtResult};
use std::sync::{Arc, RwLock};

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LedgerError {
    AccountAlreadyExists,
    AccountNotFound,
    NonPositiveAmount,
    SelfTransfer,
    InsufficientFunds,
    Overflow,
}

impl Display for LedgerError {
    fn fmt(&self, f: &mut Formatter<'_>) -> FmtResult {
        match self {
            LedgerError::AccountAlreadyExists => write!(f, "account already exists"),
            LedgerError::AccountNotFound => write!(f, "account not found"),
            LedgerError::NonPositiveAmount => write!(f, "amount must be positive"),
            LedgerError::SelfTransfer => write!(f, "cannot transfer to the same account"),
            LedgerError::InsufficientFunds => write!(f, "insufficient funds"),
            LedgerError::Overflow => write!(f, "balance overflow or underflow"),
        }
    }
}

impl Error for LedgerError {}

pub trait AccountStore: Send + Sync {
    fn open_account(&mut self, id: &str, balance: i64) -> Result<(), LedgerError>;
    fn balance(&self, id: &str) -> Result<i64, LedgerError>;
    fn transfer(&mut self, from: &str, to: &str, amount: i64) -> Result<(), LedgerError>;
}

#[derive(Debug, Default)]
pub struct MemoryStore {
    accounts: HashMap<String, i64>,
}

impl MemoryStore {
    pub fn new() -> Self {
        MemoryStore {
            accounts: HashMap::new(),
        }
    }
}

impl AccountStore for MemoryStore {
    fn open_account(&mut self, id: &str, balance: i64) -> Result<(), LedgerError> {
        if self.accounts.contains_key(id) {
            return Err(LedgerError::AccountAlreadyExists);
        }
        self.accounts.insert(id.to_string(), balance);
        Ok(())
    }

    fn balance(&self, id: &str) -> Result<i64, LedgerError> {
        self.accounts
            .get(id)
            .copied()
            .ok_or(LedgerError::AccountNotFound)
    }

    fn transfer(&mut self, from: &str, to: &str, amount: i64) -> Result<(), LedgerError> {
        if amount <= 0 {
            return Err(LedgerError::NonPositiveAmount);
        }
        if from == to {
            return Err(LedgerError::SelfTransfer);
        }

        let from_balance = match self.accounts.get(from).copied() {
            Some(b) => b,
            None => return Err(LedgerError::AccountNotFound),
        };
        let to_balance = match self.accounts.get(to).copied() {
            Some(b) => b,
            None => return Err(LedgerError::AccountNotFound),
        };

        if from_balance < amount {
            return Err(LedgerError::InsufficientFunds);
        }

        let new_from = from_balance.checked_sub(amount).ok_or(LedgerError::Overflow)?;
        let new_to = to_balance.checked_add(amount).ok_or(LedgerError::Overflow)?;

        if let Some(b) = self.accounts.get_mut(from) {
            *b = new_from;
        }
        if let Some(b) = self.accounts.get_mut(to) {
            *b = new_to;
        }
        Ok(())
    }
}

#[derive(Clone)]
pub struct Ledger {
    inner: Arc<RwLock<MemoryStore>>,
}

impl Ledger {
    pub fn new() -> Self {
        Ledger {
            inner: Arc::new(RwLock::new(MemoryStore::new())),
        }
    }

    pub fn open_account(&self, id: &str, balance: i64) -> Result<(), LedgerError> {
        let mut store = self
            .inner
            .write()
            .expect("ledger lock poisoned in open_account");
        store.open_account(id, balance)
    }

    pub fn balance(&self, id: &str) -> Result<i64, LedgerError> {
        let store = self
            .inner
            .read()
            .expect("ledger lock poisoned in balance");
        store.balance(id)
    }

    pub fn transfer(&self, from: &str, to: &str, amount: i64) -> Result<(), LedgerError> {
        let mut store = self
            .inner
            .write()
            .expect("ledger lock poisoned in transfer");
        store.transfer(from, to, amount)
    }
}

