use std::env;

use aion_ledger::Ledger;

fn parse_u64(arg: &str) -> Result<u64, String> {
    arg.parse::<u64>().map_err(|_| String::from("invalid number"))
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() != 3 || args[1] != "bench" {
        eprintln!("usage: {} bench N", args[0]);
        std::process::exit(1);
    }

    let n = match parse_u64(&args[2]) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    };

    let ledger = Ledger::new();
    ledger.open_account("A", 1_000_000).expect("open A");
    ledger.open_account("B", 1_000_000).expect("open B");

    for _ in 0..n {
        ledger.transfer("A", "B", 1).expect("transfer A->B");
        ledger.transfer("B", "A", 1).expect("transfer B->A");
    }

    let a = ledger.balance("A").expect("balance A");
    let b = ledger.balance("B").expect("balance B");
    let total = a + b;
    let operations = 2 * n;

    println!(
        "total={} a={} b={} operations={}",
        total, a, b, operations
    );
}

