import numpy as np

from pvlib import iam


def main():
    # Security / robustness properties around the AOI > 90 boundary

    # 1. Values around grazing and beyond for n = 1
    aoi_edge = np.array([89.9999, 90.0, 90.0001, 120.0, -120.0])
    out_edge = iam.physical(aoi_edge, n=1)
    out_edge = np.asarray(out_edge)
    assert out_edge.shape == aoi_edge.shape

    for aoi_val, val in zip(aoi_edge, out_edge):
        if abs(aoi_val) > 90.0:
            # Boundary property: for n = 1 and |AOI| > 90, output must be 0.0
            assert float(val) == 0.0, (
                f"For n=1 and |AOI|>90, expected 0.0, got {val!r} for AOI={aoi_val}"
            )
        else:
            # For |AOI| <= 90: result must be finite and within [0,1]
            assert np.isfinite(val), f"Non-finite IAM at AOI={aoi_val}: {val!r}"
            assert 0.0 <= float(val) <= 1.0, (
                f"IAM out of [0,1] at AOI={aoi_val}: {val!r}"
            )

    # 2. Mixed finite and NaN AOI to check NaN handling and shape/broadcasting
    aoi_mix = np.array([-100.0, np.nan, 0.0, 100.0])
    out_mix = iam.physical(aoi_mix, n=1.0)
    out_mix = np.asarray(out_mix)
    assert out_mix.shape == aoi_mix.shape

    for aoi_val, val in zip(aoi_mix, out_mix):
        if np.isnan(aoi_val):
            # Boundary property: NaN AOI propagates to NaN
            assert np.isnan(val), f"NaN AOI should yield NaN, got {val!r}"
        elif abs(aoi_val) > 90.0:
            # For n = 1 and |AOI| > 90, must be 0.0
            assert float(val) == 0.0, (
                f"For n=1 and |AOI|>90, expected 0.0, got {val!r} for AOI={aoi_val}"
            )
        else:
            # For |AOI| <= 90: bounded and finite
            assert np.isfinite(val), f"Non-finite IAM at AOI={aoi_val}: {val!r}"
            assert 0.0 <= float(val) <= 1.0, (
                f"IAM out of [0,1] at AOI={aoi_val}: {val!r}"
            )

    # 3. Simple 2D array to exercise basic broadcasting and boundary behavior
    aoi_hd = np.array([[0.0, 89.0, 91.0], [45.0, 100.0, -95.0]])
    out_hd = iam.physical(aoi_hd, n=1.0)
    out_hd = np.asarray(out_hd)
    assert out_hd.shape == aoi_hd.shape

    for aoi_val, val in zip(aoi_hd.ravel(), out_hd.ravel()):
        if abs(aoi_val) > 90.0:
            assert float(val) == 0.0, (
                f"High-dim: expected 0.0 for |AOI|>90 (AOI={aoi_val}), got {val!r}"
            )
        else:
            assert np.isfinite(val), (
                f"High-dim: non-finite IAM {val!r} for AOI={aoi_val}"
            )
            assert 0.0 <= float(val) <= 1.0, (
                f"High-dim: IAM out of [0,1] for AOI={aoi_val}: {val!r}"
            )


if __name__ == "__main__":
    main()
